    "r90.43fb3b9b7231": "<span class=\"hero-stat__value\">1</span><span class=\"hero-stat__label\">proponowany interfejs API wnioskowania, plus oddzielne narzędzia MCP</span>",
    "r90.1b51d67760cb": "<span class=\"hero-stat__value\">3</span><span class=\"hero-stat__label\">trasy wejścia — wtyczka, fork, lub natywny SDK</span>",
    "r90.dc19faaf160f": "<span class=\"hero-stat__value\">0</span><span class=\"hero-stat__label\">wymagane konta w chmurze na zamierzonej ścieżce wyłącznie lokalnej</span>",
    "v94.81b12b456e2a": "Jeden interfejs zgodny z OpenAI na",
    "v94.417dafa10633": "plus odkrywanie — opublikowane, wersjonowane, celowo nudne.",
    "v94.a9c4998c6cab": "TypeScript, Python, Swift, Kotlin — każdy z pięcioliniowym szybkim startem i przykładową aplikacją.",
    "v94.6b79a7769172": "Claude Code, agenci i IDE widzą sieć jako narzędzia od pierwszego dnia.",
    "v94.a844f9675812": "ChatGPT, Perplexity, Gemini i stosy agentów — jedna strona instalacyjna, każda aktualizowana przez nazwanego członka.",
    "v94.a13d07734bed": "Najpierw LibreChat, potem kolejne najczęściej używane otwarte klienty — cienkie forki, głośne PR-y do głównych gałęzi.",
    "v94.ef7263f6b262": "Publiczny zestaw testowy; przejdź go, a Twój klient otrzyma odznakę. Rejestr zawiera każdy certyfikowany klient.",
