    "a90.3a51ce88d3a1@alt": "Koncepcja renderu urządzenia Enki: ceramiczny kamyk wielkości dłoni w kolorze kości słoniowej z okrągłym mosiężnym przyciskiem zasilania, maleńką diodą LED baterii, pojedynczym portem USB-C i bez ekranu",
    "a90.4306523a0699@alt": "Koncepcja renderu urządzenia Enki w kolorze kości słoniowej trzymanego w dłoni, z telefonem uruchamiającym aplikację towarzyszącą, inteligentnymi okularami i słuchawkami na stole za nim",
    "meta90.aa6a48227049@content": "Urządzenie Enki to kieszonkowa koncepcja lokalnej sztucznej inteligencji, jeszcze nie produkt. Poznaj jego cele inżynieryjne, otwarte założenia projektowe, ograniczenia i proponowaną rolę w domowej sieci mesh.",
    "r90.cdb263af2652": "Enki — Inteligencja należy do wszystkich, wszędzie",
    "r90.a13f6e8e8987": "<span class=\"hero-stat__value\">÷280</span><span class=\"hero-stat__label\">koszt wnioskowania klasy GPT-3.5, listopad 2022 → październik 2024</span>",
    "r90.08de2ea5b485": "<span class=\"hero-stat__value\">3,8 mld</span><span class=\"hero-stat__label\">Phi-3-mini: postęp specyficzny dla benchmarku, nie uniwersalna równoważność</span>",
    "r90.20e759dae0ce": "<span class=\"hero-stat__value\">20+</span><span class=\"hero-stat__label\">lokalnych modeli przetestowanych w badaniu IPW</span>",
    "r90.df10a9fbad65": "<span class=\"hero-stat__value\">300</span><span class=\"hero-stat__label\">docelowych członków, w tym założyciel</span>",
    "r90.9f1651d393eb": "Przeczytaj manifest <span class=\"arr\">→</span>",
    "home94.clientKicker": "03 · Klient",
    "home94.clientDescription": "Połącz aplikacje, których używasz, ze sztuczną inteligencją na sprzęcie, który kontrolujesz. Proponowane integracje i lokalna pamięć, którą możesz przenosić między klientami.",
    "home94.clientLink": "Poznaj klienta <span class=\"arr\">→</span>",
